const v = msg.payload;
msg.payload = (v === 1 || v === "1" || v === true);
return msg;

// Map of key IDs to names
const keyMap = {
    "27184202138": "Blue Chip",
    "11679151219": "White Card",
    "ABCDEF12": "Other"
};

flow.set("booking_key", msg.payload);
flow.set("booking_key_name", keyMap[msg.payload] || msg.payload);

return null;

// Get values
let dtString = flow.get("booking_datetime");
let keyId = flow.get("booking_key");
let keyName = flow.get("booking_key_name");

// Parse datetime string
let dt = new Date(dtString);

// Format for Vienna timezone
let options = {
    timeZone: "Europe/Vienna",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit"
};
let formatted = new Intl.DateTimeFormat("de-AT", options).format(dt);

// Calculate delay until booking time
let now = new Date();
let delayMs = dt.getTime() - now.getTime();

if (delayMs < 0) {
    node.warn("Booking time is in the past");
    return null;
}

// Message to send after delay
msg.payload = keyId;
msg.delay = delayMs;
msg.display = `${formatted} – ${keyName}`;
return msg;

let v = msg.payload;
node.warn("payload: " + v);
flow.set("partySelectedTs", v);

return msg;

const OFFSET_MS = 60 * 60 * 1000; // 1 Stunde
const now = Date.now() + OFFSET_MS;

const partyMs = 60 * 1000;
const windowMs = 60 * 1000;

function fmtTodayOrDateUTC(ts) {
  const nowD = new Date();
  const d = new Date(ts);

  const sameDay =
    nowD.getUTCFullYear() === d.getUTCFullYear() &&
    nowD.getUTCMonth() === d.getUTCMonth() &&
    nowD.getUTCDate() === d.getUTCDate();

  const HH = String(d.getUTCHours()).padStart(2, "0");
  const MM = String(d.getUTCMinutes()).padStart(2, "0");

  if (sameDay) return `HEUTE ${HH}:${MM}`;

  const yyyy = d.getUTCFullYear();
  const mm = String(d.getUTCMonth() + 1).padStart(2, "0");
  const dd = String(d.getUTCDate()).padStart(2, "0");
  return `${dd}.${mm}.${yyyy} ${HH}:${MM}`;
}

// Anzeige nur senden, wenn Text sich ändert
function emitUi(text) {
  const last = flow.get("partyLastUiText") || "";
  if (text === last) return null;
  flow.set("partyLastUiText", text);
  return { topic: "resort/house3/party/next", payload: text };
}

// --- A) Buchung übernehmen (nur wenn bestätigt) ---
const req = flow.get("partyBookRequest");
//node.warn("cron: bookRequest:" + req);

if (typeof req === "number" && Number.isFinite(req)) {
  flow.set("partyBookRequest", null); // konsumieren (Event)

  const ts = req; // bereits Timestamp in ms

  flow.set("partyBookingTs", ts);
  flow.set("partyTriggered", false);
  flow.set("partyRunningUntilTs", 0);

  node.warn("cron: consumed request ts=" + ts);

  return [null, emitUi(`${fmtTodayOrDateUTC(ts)}`)];
}

// --- B) Laufzeitverwaltung ---
const bookingTs = flow.get("partyBookingTs");
const triggered = flow.get("partyTriggered") || false;
const runningUntil = flow.get("partyRunningUntilTs") || 0;

if (!bookingTs) return [null, emitUi("keine Buchung")];

if (runningUntil && now >= runningUntil) {
  flow.set("partyRunningUntilTs", 0);
  flow.set("partyTriggered", false);
  flow.set("partyBookingTs", null);
  return [null, emitUi("keine Buchung")];
}

if (!triggered && now > bookingTs + windowMs) {
  flow.set("partyBookingTs", null);
  flow.set("partyTriggered", false);
  flow.set("partyRunningUntilTs", 0);
  return [null, emitUi("keine Buchung")];
}

if (!triggered && now >= bookingTs && now <= bookingTs + windowMs) {
  flow.set("partyTriggered", true);
  const until = now + partyMs;
  flow.set("partyRunningUntilTs", until);

  const outCmd = { topic: "resort/house3/party/cmd", payload: "PARTY" };
  const outUi = emitUi(`Party läuft bis: ${fmtTodayOrDateUTC(until)}`);

  return [outCmd, outUi];
}

// noch zu früh: Next (nur wenn geändert)
return [null, emitUi(`${fmtTodayOrDateUTC(bookingTs)}`)];

let raw = flow.get("partySelectedTs");
flow.set("partyBookRequest", raw);
flow.set("partyBookRequestTs", Date.now()); 

return null;

const OFFSET_MS = 0; // 60 * 60 * 1000; // 1 Stunde
const now = new Date(Date.now() + OFFSET_MS);

const HH = String(now.getHours()).padStart(2, "0");
const MM = String(now.getMinutes()).padStart(2, "0");
const SS = String(now.getSeconds()).padStart(2, "0");

msg.payload = `${HH}:${MM}:${SS}`;
return msg;

// ===============================
// GAS PARSER – Haus 4 (FIX: Broadcast ON/OFF)
// ===============================

// 0) Messwert
let v = Number(msg.payload);
if (isNaN(v)) {
    return [null, null, null, null, null, null, null, null, null];
}

// 1) Grenzwert
let limit = Number(flow.get('gas_limit')) || 300;

// 2) Alarm berechnen
let alarm = v >= limit;

// 3) Gauge
let msgGauge = { payload: v };

// 4) LED Haus 4
let msgLed = {
    topic: "haus4/gas/led",
    payload: alarm,
    retain: true
};

// 5) Text Haus 4
let msgText = {
    topic: "haus4/gas/statusText",
    payload: alarm ? "Gasalarm" : "Normal",
    retain: true
};

// 6) Mittelwert
let buf = flow.get('gas_buffer') || [];
buf.push(v);
if (buf.length > 6) buf.shift();

let msgAvg = null;
if (buf.length === 6) {
    let sum = buf.reduce((a, b) => a + b, 0);
    let avg = sum / buf.length;
    msgAvg = { payload: avg };
}
flow.set('gas_buffer', buf);

// 7) Broadcast ESP + zentraler Gas-Broadcast (JETZT IMMER!)
let bcMsgs = null;
if (alarm) {
    // ALARM → ON
    bcMsgs = [
        {
            topic: "haus4/gas/alarm",
            payload: "Gasalarm Haus 4"
        },
        {
            topic: "resort/bc/gas",
            payload: "ON",
            retain: true
        }
    ];
} else {
    // NORMAL → OFF (Reset!)
    bcMsgs = [
        {
            topic: "resort/bc/gas",
            payload: "OFF",
            retain: true
        }
    ];
}

// 8) globale Flags
global.set('house4_gas_alarm', alarm);
global.set('house4_gas_status', alarm ? "ALARM" : "NORMAL");

// 9) LED fürs Auswahldashboard
let msgSelLed = {
    topic: "resort/house4/status/gas",
    payload: alarm,
    retain: true
};

// 10) Status fürs Auswahldashboard
let stormAlarm = global.get('house4_storm_alarm') || false;
let houseText = (alarm || stormAlarm) ? "ALARM" : "NORMAL";

let msgSelStatus = {
    topic: "resort/house4/status",
    payload: houseText,
    retain: true
};

// Outputs (9)
return [
    msgGauge,      // 1: Gauge
    msgLed,        // 2: LED Haus 4
    msgText,       // 3: Text Haus 4
    msgAvg,        // 4: Mittelwert
    bcMsgs,        // 5: Array -> MQTT-OUT "Gas BC OUT"
    msgSelLed,     // 6: LED Auswahl
    msgSelStatus,  // 7: Status Auswahl
    null,          // 8: frei
    null           // 9: frei
];

// wird vom UI-Button "GASALARM RESET" ausgelöst

// Slider auf 500 setzen
msg.payload = 500;          // Zahl
msg.topic = "Grenzwert";  // wie im Slider-Node eintragen

// optional: Mittelwert-Puffer leeren
flow.set('gas_buffer', []);

// an Slider AUSGEBEN
return msg;

// 0) LETZTEN Zustand laden
let lastStorm = global.get('house4_storm_last') || false;

// 1) NEUEN Zustand berechnen
let newStorm = (msg.payload === "ON");

// 2) NUR bei Änderung!
if (newStorm !== lastStorm) {
    global.set('house4_storm_last', newStorm);
    global.set('house4_storm_alarm', newStorm);
    global.set('house4_storm_status', newStorm ? 'STURM' : 'NORMAL');

    // Gas-Status
    let gasAlarm = global.get('house4_gas_alarm') || false;
    let houseText = (gasAlarm || newStorm) ? "ALARM" : "NORMAL";

    // Outputs
    let msgLed = {
        topic: "resort/house4/status/storm",
        payload: newStorm
    };

    let msgText = {
        topic: "resort/house4/status",
        payload: houseText,
        retain: true
    };

    let msgEsp = {
        topic: "resort/bc/storm",
        payload: newStorm ? "ON" : "OFF",
        retain: true
    };

    node.warn("STURM BC: " + msgEsp.payload + " (letzte: " + lastStorm + ")");
    return [msgLed, msgText, msgEsp];
}

node.warn("STURM gleich: " + newStorm + " -> KEIN BC");
return null;  // KEIN Flood!

// KOMPLETT ersetzen!
let lastParty = flow.get('house4_party_last') || false;
let party = (msg.payload === "ON");

node.warn("FORCE INPUT: " + msg.payload + " (letzte: " + lastParty + ")");

// NUR bei Änderung!
if (party !== lastParty) {
    flow.set('house4_party_last', party);
    node.warn("FORCE BC CHANGE: " + (party ? "ON" : "OFF"));

    // DASHBOARD
    msg.topic = "resort/house4/status/party";
    msg.payload = party;

    // ESP32 BC
    let msgEsp = {
        topic: "resort/bc/party",
        payload: party ? "ON" : "OFF",
        retain: true
    };

    return [msg, msgEsp];
} else {
    node.warn("KEIN CHANGE: " + (party ? "ON" : "OFF"));
    return null;  // Nichts senden!
}

// ======================================
// GRENZWERT - Haus 4 Gas (Slider + Reset) DEBUG
// ======================================

node.warn("INPUT: topic=" + msg.topic + " payload=" + msg.payload + " reset=" + msg.reset);

if (msg.reset === true) {
    msg.payload = 500;          
    node.warn("RESET → Grenzwert = 500");
}

let limit = Number(msg.payload);
flow.set('gas_limit', limit);
node.warn("flow.set('gas_limit', " + limit + ")");

msg.topic = "haus4/gaslimit";
node.warn("OUTPUT MQTT: haus4/gaslimit = " + limit);

return msg;
